import frappe
from frappe import _
from frappe.model.document import Document
from frappe.utils import now_datetime

from nexaploy.billing import payouts_utils as pou


class PublisherPayout(Document):
	"""Monthly revenue share of a Marketplace Publisher, generated by
	nexaploy.billing.payouts.generate_publisher_payouts. Staff move it Draft -> Approved ->
	Paid in the desk; Credits payouts are credited to the publisher team when Paid."""

	def validate(self):
		before = None if self.is_new() else self.get_doc_before_save()
		old = before.status if before else pou.DRAFT
		try:
			pou.check_payout_transition(old, self.status)
		except pou.PayoutError as exc:
			frappe.throw(_(str(exc)))
		if before and old != pou.DRAFT and self._amounts_changed(before):
			frappe.throw(_("Only Draft payouts can change their amounts"))
		if not self.payout_method:
			self.payout_method = frappe.db.get_value("Marketplace Publisher", self.publisher, "payout_method")
		if self.status == pou.PAID and old != pou.PAID:
			self.paid_on = now_datetime()
			if self.payout_method != "Credits" and not (self.payment_reference or "").strip():
				frappe.throw(_("Enter the transfer reference before marking the payout Paid"))

	def _amounts_changed(self, before):
		def key(doc):
			return (
				float(doc.gross or 0), float(doc.net or 0), float(doc.platform_fee or 0),
				tuple((i.invoice_item, float(i.amount or 0), float(i.share or 0)) for i in doc.items),
			)
		return key(before) != key(self)

	def on_update(self):
		before = self.get_doc_before_save()
		old = before.status if before else pou.DRAFT
		if old == self.status:
			return
		if pou.credits_due(self.payout_method, old, self.status, bool(self.credit_transaction)) and (self.net or 0) > 0:
			from nexaploy.billing.credits import add_credits

			team = frappe.db.get_value("Marketplace Publisher", self.publisher, "team")
			tx = add_credits(
				team,
				self.net,
				"Adjustment",
				(self.doctype, self.name),
				description=_("Marketplace payout {0} ({1} to {2})").format(self.name, self.period_start, self.period_end),
				currency=self.currency,
			)
			self.db_set("payment_reference", self.payment_reference or tx)
			self.db_set("credit_transaction", tx)
		from nexaploy.billing.payouts import on_payout_status_change

		on_payout_status_change(self, old)

	def on_trash(self):
		if self.status != pou.DRAFT:
			frappe.throw(_("Only Draft payouts can be deleted"))

	@frappe.whitelist()
	def set_status(self, status, payment_reference=None):
		"""Desk buttons: Approve / Back to Draft / Mark Paid."""
		frappe.only_for("System Manager")
		self.status = status
		if payment_reference:
			self.payment_reference = payment_reference
		self.save()
		return self.status
